import React, { useState, useEffect, useRef } from 'react';

interface ImageProps {
    src: string;
    width: number;
    height: number;
    alt: string;
    className?: string;
}

const Image: React.FC<ImageProps> = ({ src, width, height, alt, className }) => {
    const [resizedSrc, setResizedSrc] = useState<string>('');
    const imgRef = useRef<HTMLImageElement | null>(null);

    useEffect(() => {
        if (src) {
            const image = imgRef.current;
            if (image) {
                const canvas = document.createElement('canvas');
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    // Set canvas size to the target width and height
                    canvas.width = width;
                    canvas.height = height;

                    // Draw image on canvas
                    ctx.drawImage(image, 0, 0, width, height);

                    // Convert canvas to base64 data URL
                    const resizedImage = canvas.toDataURL();
                    setResizedSrc(resizedImage);
                }
            }
        }
    }, [src, width, height]);

    return (
        <img
            ref={imgRef}
            src={resizedSrc || src} // Use resized image if available
            alt={alt}
            width={width}
            height={height}
            className={className}
        />
    );
};

export default Image;
